import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { format } from 'date-fns';
import api from '../services/api';
import { useAuth } from '../context/AuthContext';
import LoadingSpinner from '../components/LoadingSpinner';
import toast from 'react-hot-toast';

const Dashboard = () => {
    const { user } = useAuth();
    const [loading, setLoading] = useState(true);
    const [upcomingEvents, setUpcomingEvents] = useState([]);
    const [pastEvents, setPastEvents] = useState([]);
    const [summary, setSummary] = useState(null);

    useEffect(() => {
        fetchDashboardData();
    }, []);

    const fetchDashboardData = async () => {
        try {
            const [registrationsRes, summaryRes] = await Promise.all([
                api.get('/dashboard/registrations'),
                api.get('/dashboard/summary')
            ]);

            setUpcomingEvents(registrationsRes.data.upcoming);
            setPastEvents(registrationsRes.data.past);
            setSummary(summaryRes.data);
        } catch (error) {
            console.error('Error fetching dashboard data:', error);
            toast.error('Failed to load dashboard data');
        } finally {
            setLoading(false);
        }
    };

    const handleCancel = async (eventId) => {
        try {
            await api.delete(`/events/${eventId}/register`);
            toast.success('Registration cancelled');
            fetchDashboardData();
        } catch (error) {
            const message = error.response?.data?.message || 'Cancellation failed';
            toast.error(message);
        }
    };

    if (loading) return <LoadingSpinner />;

    return (
        <div className="min-h-screen bg-gray-50 py-8">
            <div className="container mx-auto px-4">
                <h1 className="text-3xl font-bold mb-8 text-gray-800">
                    Welcome back, {user?.name}!
                </h1>

                {/* Summary Cards */}
                {summary && (
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
                        <div className="bg-white rounded-lg shadow p-6">
                            <div className="text-sm text-gray-500 mb-1">Total Registrations</div>
                            <div className="text-3xl font-bold text-purple-600">
                                {summary.totalRegistrations}
                            </div>
                        </div>
                        <div className="bg-white rounded-lg shadow p-6">
                            <div className="text-sm text-gray-500 mb-1">Upcoming Events</div>
                            <div className="text-3xl font-bold text-green-600">
                                {summary.upcomingCount}
                            </div>
                        </div>
                        <div className="bg-white rounded-lg shadow p-6">
                            <div className="text-sm text-gray-500 mb-1">Past Events</div>
                            <div className="text-3xl font-bold text-gray-600">
                                {summary.pastCount}
                            </div>
                        </div>
                    </div>
                )}

                {/* Next Event */}
                {summary?.nextEvent && (
                    <div className="bg-gradient-to-r from-purple-600 to-blue-600 text-white rounded-lg shadow-lg p-6 mb-8">
                        <h2 className="text-lg font-semibold mb-2">Your Next Event</h2>
                        <div className="flex justify-between items-center">
                            <div>
                                <h3 className="text-2xl font-bold mb-1">{summary.nextEvent.name}</h3>
                                <p>{format(new Date(summary.nextEvent.date), 'PPP')}</p>
                                <p>{summary.nextEvent.location}</p>
                            </div>
                            <Link
                                to={`/event/${summary.nextEvent._id}`}
                                className="bg-white text-purple-600 px-6 py-3 rounded-lg hover:bg-gray-100 transition"
                            >
                                View Details
                            </Link>
                        </div>
                    </div>
                )}

                {/* Upcoming Events */}
                <div className="mb-8">
                    <h2 className="text-2xl font-bold mb-4 text-gray-800">
                        Upcoming Events ({upcomingEvents.length})
                    </h2>
                    {upcomingEvents.length === 0 ? (
                        <div className="bg-white rounded-lg shadow p-8 text-center">
                            <p className="text-gray-500 mb-4">No upcoming events</p>
                            <Link
                                to="/events"
                                className="bg-purple-600 text-white px-6 py-3 rounded-lg hover:bg-purple-700 transition inline-block"
                            >
                                Browse Events
                            </Link>
                        </div>
                    ) : (
                        <div className="grid grid-cols-1 gap-4">
                            {upcomingEvents.map(({ event }) => (
                                <div key={event._id} className="bg-white rounded-lg shadow p-6">
                                    <div className="flex justify-between items-start">
                                        <div>
                                            <h3 className="text-xl font-semibold text-gray-800 mb-2">
                                                {event.name}
                                            </h3>
                                            <div className="space-y-1 text-sm text-gray-600">
                                                <p>📅 {format(new Date(event.date), 'PPP')}</p>
                                                <p>📍 {event.location}</p>
                                                <p>👤 {event.organizer}</p>
                                            </div>
                                        </div>
                                        <div className="flex space-x-3">
                                            <Link
                                                to={`/event/${event._id}`}
                                                className="bg-purple-600 text-white px-4 py-2 rounded-lg hover:bg-purple-700 transition"
                                            >
                                                View
                                            </Link>
                                            <button
                                                onClick={() => handleCancel(event._id)}
                                                className="bg-red-600 text-white px-4 py-2 rounded-lg hover:bg-red-700 transition"
                                            >
                                                Cancel
                                            </button>
                                        </div>
                                    </div>
                                </div>
                            ))}
                        </div>
                    )}
                </div>

                {/* Past Events */}
                {pastEvents.length > 0 && (
                    <div>
                        <h2 className="text-2xl font-bold mb-4 text-gray-800">
                            Past Events ({pastEvents.length})
                        </h2>
                        <div className="grid grid-cols-1 gap-4">
                            {pastEvents.map(({ event }) => (
                                <div key={event._id} className="bg-white rounded-lg shadow p-6 opacity-75">
                                    <div className="flex justify-between items-start">
                                        <div>
                                            <h3 className="text-xl font-semibold text-gray-600 mb-2">
                                                {event.name}
                                            </h3>
                                            <div className="space-y-1 text-sm text-gray-500">
                                                <p>📅 {format(new Date(event.date), 'PPP')}</p>
                                                <p>📍 {event.location}</p>
                                                <p>👤 {event.organizer}</p>
                                            </div>
                                        </div>
                                        <Link
                                            to={`/event/${event._id}`}
                                            className="bg-gray-600 text-white px-4 py-2 rounded-lg hover:bg-gray-700 transition"
                                        >
                                            View
                                        </Link>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
};

export default Dashboard;
